INSERT INTO changelog_entries(version,title,summary,content,category,published_at,affected_route,created_at,updated_at) SELECT '2.55.1','Актуален SEO отчет и по-ясни резултати при търсене','SEO обзорът показва последните завършени проверки. Заглавията са по-кратки, а изтеклите обявени срокове са ясно обозначени.','["Историческите проблеми остават в историята и не се смесват с текущия резултат. Коригирани са броят на процедурите и показаният кеш на картата на сайта.","Процедурите и програмите имат кратки, различими метаданни, без дълги вътрешни идентификатори. Официалните връзки се проверяват по същите правила като публичните страници.","Изтекъл обявен срок показва предупреждение за проверка на официалния източник, без автоматично да затваря многоетапни приеми.","Добавена е текстова карта на сайта със същия валидиран списък от адреси като XML картата. Приемането от Google се проверява отделно."]','fix','2026-09-19','/admin',datetime('now'),datetime('now') WHERE NOT EXISTS (SELECT 1 FROM changelog_entries WHERE version='2.55.1');
